n647.content:
\begin{lemma}\label{fermatLastTheoremThree}\lean{fermatLastTheoremThree}\leanok
\discussion{16}
  There are no solutions in positive integers to $a^3+b^3=c^3$.
\end{lemma}

n648.content:
\begin{proof}
  \leanok
