n659.content:
\begin{corollary}
  \label{FreyPackage.false}
  \lean{FLT.Bosses.B3_proof}
  \uses{Mazur_Frey, Wiles_Frey}
  \leanok
  There is no Frey package.
\end{corollary}

n660.content:
\begin{proof} Follows immediately from the previous two
  theorems~\ref{Mazur_Frey} and~\ref{Wiles_Frey}.
\end{proof}

n661.content:
\begin{corollary}
  \label{FLT}
  \lean{flt}
  \leanok
  Fermat's Last Theorem is true. In other words, there are no positive integers $a,b,c$ and
  natural $n\geq3$ such that $a^n+b^n=c^n$.
\end{corollary}

n662.content:
\begin{proof}
  \uses{FermatLastTheorem.of_p_ge_5, FreyPackage.false, FreyPackage.of_not_FermatLastTheorem_p_ge_5}
  Assume there is a there is a counterexample $a^n+b^n=c^n$.
  By Corollary \ref{FermatLastTheorem.of_p_ge_5} we may assume that there is also a counterexample
  $a^p+b^p=c^p$ with $p\geq 5$ and prime.
  Then there is a Frey package $(a,b,c,p)$ by~\ref{FreyPackage.of_not_FermatLastTheorem_p_ge_5},
  contradicting Corollary~\ref{FreyPackage.false}.
\end{proof}

n664.content:
\begin{definition}
  \lean{GaloisRepresentation.IsHardlyRamified}
  \label{hardly_ramified}
  \leanok
  Let $R$ be a coefficient ring with finite residue field of characteristic $\ell\geq3$.
  Let $V$ be a finite free $R$-module of rank~2, equipped with the product topology. A
  continuous representation $\rho: \Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to \GL_R(V)$ is said to be \emph{hardly ramified} if it
  satisfies the following four conditions:
  \begin{enumerate}
  \item $\det(\rho):\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to R^\times$ is the cyclotomic character;
  \item $\rho$ is unramified outside $2\ell$;
  \item The restriction of $\rho$ to $\Gal(\overline{\mathbb{Q}}_2/\mathbb{Q}_2)$ is reducible (more precisely,
  there is a short exact sequence $0\to R\to V\to R\to 0$ which is stable
  under the action of $\Gal(\overline{\mathbb{Q}}_2/\mathbb{Q}_2)$) and the Galois action on the 1-dimensional
  quotient is an unramified representation of $\Gal(\overline{\mathbb{Q}}_2/\mathbb{Q}_2)$ whose square is trivial;
  \item The restriction of $\rho$ to $\Gal(\overline{\mathbb{Q}}_\ell/\mathbb{Q}_\ell)$ is flat, by which we mean that for all open
  ideals $I$ of $R$, the (finite image) representation $\rho$ mod $I:\Gal(\overline{\mathbb{Q}}_\ell/\mathbb{Q}_\ell)\to \GL_{R/I}(V/I)$
  comes from a finite flat group scheme.
  \end{enumerate}
\end{definition}

n665.content:
\begin{theorem}
  \lean{FreyCurve.torsion_isHardlyRamified}
  \label{Frey_curve_hardly_ramified}
  \uses{hardly_ramified}
  \leanok
  The $\ell$-torsion $\rho:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(\mathbb{Z}/\ell\mathbb{Z})$ in the Frey curve associated to a Frey
  package $(a,b,c,\ell)$ is hardly ramified.
\end{theorem}

n667.content:
\begin{theorem}
  \lean{FreyCurve.torsion_not_isIrreducible}
  \label{hardly_ramified_reducible}
  \leanok
  If $\ell\geq 3$ is a prime and $\rho:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(\mathbb{Z}/\ell\mathbb{Z})$ is hardly ramified,
  then $\rho$ is reducible.
\end{theorem}

n668.content:
\begin{theorem}
  \label{Wiles_Frey_again}
  \lean{FLT.Bosses.B4_proof}
  \leanok
  If $\overline{\rho}$ is the mod $p$ Galois representation associated to a Frey package $(a,b,c,p)$ then
  $\overline{\rho}$ is reducible.
\end{theorem}

n669.content:
\begin{proof}
  \uses{Frey_curve_hardly_ramified,hardly_ramified_reducible}
  Indeed, $\rho$ is hardly ramified by theorem~\ref{Frey_curve_hardly_ramified}
  and thus reducible by theorem~\ref{hardly_ramified_reducible}.
\end{proof}

n670.content:
\begin{theorem}
  \lean{GaloisRepresentation.IsHardlyRamified.lifts}
  \label{hardly_ramified_lifts}
  \uses{hardly_ramified}
  \leanok
  If $\ell\geq3$ is prime and $\overline{\rho}:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(\mathbb{Z}/\ell\mathbb{Z})$
  is hardly ramified and irreducible, then there exists a finite extension~$K$ of $\mathbb{Q}_\ell$
  with integer ring~$\mathcal{O}$ and maximal ideal $\mathfrak{m}$
  and a hardly ramified representation
  $\rho:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(\mathcal{O})$ whose reduction modulo~$\mathfrak{m}$ is isomorphic to $\rho$.
\end{theorem}

n672.content:
\begin{theorem}
  \lean{GaloisRepresentation.IsHardlyRamified.mem_isCompatible}
  \label{hardly_ramified_spreads_out}
  \uses{hardly_ramified}
  \leanok
  If $\ell\geq3$ is prime, $K$ is a finite extension of $\mathbb{Q}_\ell$
  with integers $\mathcal{O}$ and if $\rho:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(\mathcal{O})$ is a hardly ramified representation
  whose reduction is irreducible,
  then there exists a number field $M$ and, for each finite place $\mu$ of $M$
  of characteristic prime to 2, with completion $M_\mu$ having integer ring $R_\mu$,
  a hardly ramified semisimple representation $\rho_\mu:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(R_\mu)$ (by which we
  mean the generic fibre is semisimple), with the following properties:
  \begin{itemize}
    \item There is some $\lambda\mid\ell$ of $M$ such that $\rho_\lambda\cong\rho$,
      the isomorphism happening over some appropriate local field containing a copy
      of $M_\lambda$ and a copy of~$K$;
    \item If $\mu_1$ and $\mu_2$ are two finite places of $M$ with odd residue characteristics $m_1$
      and $m_2$, and if $p\nmid 2m_1m_2$ is prime, then $\rho_{\mu_1}$ and $\rho_{\mu_2}$
      are both unramified at~$p$ and the characteristic polynomials $\rho_{\mu_1}(\Frob_p)$
      and $\rho_{\mu_2}(\Frob_p)$ lie in $M[X]$ and are equal.
  \end{itemize}
\end{theorem}

n674.content:
\begin{theorem}
  \lean{GaloisRepresentation.IsHardlyRamified.mod_three}
  \label{hardly_ramified_mod3_reducible}
  \uses{hardly_ramified}
  \leanok
  Suppose $k$ is a finite field of characteristic 3, and suppose
  $\overline{rho}:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(k)$ is hardly ramified. Then $\overline{\rho}$ is an extension
  of the cyclotomic character by the trivial representation.
\end{theorem}

n676.content:
\begin{theorem}
  \lean{GaloisRepresentation.IsHardlyRamified.three_adic}
  \label{hardly_ramified_3adic_reducible}
  \uses{hardly_ramified, hardly_ramified_mod3_reducible}
  \leanok
  Suppose $L/\mathbb{Q}_3$ is a finite extension, with integer ring $\mathcal{O}_L$, and suppose
  $\rho_3:\Gal(\overline{\mathbb{Q}}/\mathbb{Q})\to\GL_2(\mathcal{O}_L)$ is hardly ramified. Then (considered as a representation
  to $\GL_2(L)$) $\rho_3^{ss}=1\oplus\chi_3$
  where $1$ is the trivial character and $\chi_3$ is the 3-adic cyclotomic character.
\end{theorem}

n679.content:
\begin{theorem}
    \label{modularity_lifting_theorem}
    \uses{Skinner_Wiles_CFT_trick,local_galois_coh_dim_two,local_galois_coh_top_degree,
      local_galois_coh_poincare,local_galois_coh_euler_poincare,IsDedekindDomain.FiniteAdeleRing.baseChangeAlgEquiv,
      automorphic_representation_local_decomposition,cuspidal_automorphic_representation,
