n682.content:
\begin{lemma}
    \label{ZHat.commRing}
    \lean{ZHat.commRing}
    \uses{ZHat}
    \leanok
    $\widehat{\mathbb{Z}}$ is a subring of $\prod_{N\geq1}(Z/N\mathbb{Z})$ and in particular is a ring.
\end{lemma}

n685.content:
\begin{proof}
    \leanok
    Recall that you can evaluate an element of $\widehat{\mathbb{Z}}$ at a positive integer.
    Evaluating $0$ at 2 gives $0$, and evaluating $1$ at $2$ gives $1$, and these
    are distinct elements of $\mathbb{Z}/2\mathbb{Z}$, so $0\not=1$ in $\widehat{\mathbb{Z}}$.
\end{proof}

n686.content:
\begin{lemma}
    \label{ZHat.charZero}
    \lean{ZHat.charZero}
    \leanok
    The map from the naturals into $\widehat{\mathbb{Z}}$ sending $n$ to $n$ is injective.
\end{lemma}

n687.content:
\begin{proof}
    \leanok
    Generalise the above idea. Feel free to write up a LaTeX proof and PR it.
\end{proof}

n688.content:
\begin{definition}
    \label{ZHat.e}
    \lean{ZHat.e}
    \uses{ZHat.commRing}
    \leanok
    The infinite sum $0!+1!+2!+3!+4!+5!+\cdots$ looks
    like it makes no sense at all; it is the sum of an infinite series of larger and larger
    positive numbers.
    However, the sum is \emph{finite} modulo $N$ for every positive integer $N$, because
    all the terms from $N!$ onwards are multiples of $N$ and thus are zero in $\mathbb{Z}/N\mathbb{Z}$.
    Thus it makes sense to define $e_N$ to be the value of the finite sum modulo $N$.
    Explicitly, $e_N=0!+1!+\cdots+(N-1)!$ modulo $N$.
\end{definition}

n689.content:
\begin{lemma}
    \label{ZHat.e_def}
    \lean{ZHat.e_def}
    \uses{ZHat.e}
    \leanok
    The collection $(e_N)_N$ is an element of $\widehat{\mathbb{Z}}$.
\end{lemma}

n690.content:
\begin{proof}
    \leanok
    This boils down to checking that $D!+(D+1)!+\cdots+(N-1)!$ is a multiple of~$D$.
\end{proof}

n691.content:
\begin{lemma}
    \label{ZHat.e_not_in_Int}
    \lean{ZHat.e_not_in_Int}
    \uses{ZHat.e}
    \leanok
    The element $(e_N)_N$ of $\widehat{\mathbb{Z}}$ is not in $\mathbb{Z}$.
\end{lemma}

n693.content:
\begin{lemma}
    \label{ZHat.torsionfree}
    \lean{ZHat.torsionfree}
    \uses{ZHat.commRing, ZHat.charZero}
    \leanok
    If $0<N$ is an integer then multiplication by $N$ is injective on $\widehat{\mathbb{Z}}$.
\end{lemma}

n695.content:
\begin{lemma}
    \label{ZHat.multiples}
    \lean{ZHat.multiples}
    \uses{ZHat.commRing}
    \leanok
    The multiples of~$N$ in $\widehat{\mathbb{Z}}$ are precisely the compatible collections $(z_i)_i\in\widehat{\mathbb{Z}}$
    with $z_N=0$.
\end{lemma}

n697.content:
\begin{definition}
    \label{QHat}
    \lean{QHat}
    \uses{ZHat}
    \leanok
    % blue node
    The profinite completion $\widehat{\mathbb{Q}}$ of $\mathbb{Q}$ is the tensor product $\mathbb{Q}\otimes_{\mathbb{Z}}\widehat{\mathbb{Z}}$,
    or $\widehat{\mathbb{Q}}=\mathbb{Q}\otimes\widehat{\mathbb{Z}}$ for short.
\end{definition}

n698.content:
\begin{example} Recall that the sum of all the factorials is an element $e\in\widehat{\mathbb{Z}}$, and $22/7$ is certainly
a rational number, so we can make the element $\frac{22}{7}\otimes_te\in\widehat{\mathbb{Q}}$.
\end{example}

n700.content:
\begin{lemma}
    \label{QHat.canonicalForm}
    \lean{QHat.canonicalForm}
    \uses{QHat,ZHat.commRing}
    \leanok
    Every element of $\widehat{\mathbb{Q}}:=\mathbb{Q}\otimes\widehat{\mathbb{Z}}$ can be written as $q\otimes_t z$ with $q\in\mathbb{Q}$ and $z\in\widehat{\mathbb{Z}}$.
    Furthermore one can even assume that $q=\frac{1}{N}$ for some positive integer $N$.
\end{lemma}

n702.content:
\begin{definition}
    \label{QHat.IsCoprime}
    \lean{QHat.IsCoprime}
    \uses{ZHat.commRing}
    \leanok
    If $N\in\mathbb{N}^+$ and $z\in\widehat{\mathbb{Z}}$ then we say that $N$ and $z$ are \emph{coprime} if
    $z_N\in(\mathbb{Z}/N\mathbb{Z})^\times$. We write $z/N$ as notation
    for the element $\frac{1}{N}\otimes_tz$.
\end{definition}

n703.content:
\begin{lemma}
    \label{QHat.lowestTerms}
    \lean{QHat.lowestTerms}
    \uses{QHat.IsCoprime}
    \leanok
    Every element of $\widehat{\mathbb{Q}}$ can be uniquely written as $z/N$ with $z\in\widehat{\mathbb{Z}}$, $N\in\mathbb{N}^+$,
    and with $N$ and $z$ coprime.
\end{lemma}

n705.content:
\begin{lemma}
    \label{QHat.injective_rat}
    \lean{QHat.injective_rat}
    \uses{QHat,ZHat.commRing}
    \leanok
    The ring homomorphism $\mathbb{Q}\to\widehat{\mathbb{Q}}$ sending $q$ to $q\otimes_t 1$
    is injective.
\end{lemma}

n707.content:
\begin{lemma}
    \label{QHat.injective_zHat}
    \lean{QHat.injective_zHat}
    \uses{QHat, ZHat.torsionfree}
    \leanok
    The ring homomorphism $\widehat{\mathbb{Z}}\to\widehat{\mathbb{Q}}$ sending
    $z$ to $1\otimes_t z$ is injective.
\end{lemma}

n709.content:
\begin{lemma}
    \label{QHat.rat_meet_zHat}
    \lean{QHat.rat_meet_zHat}
    \uses{QHat,ZHat.commRing}
    \leanok
    The intersection of $\mathbb{Q}$ and $\widehat{\mathbb{Z}}$ in $\widehat{\mathbb{Q}}$ is $\mathbb{Z}$.
\end{lemma}

n710.content:
\begin{proof}
    \uses{QHat.lowestTerms}
    \leanok
    Clearly $\mathbb{Z}\subseteq\mathbb{Q}\cap\widehat{\mathbb{Z}}$. Now suppose that $x\in\mathbb{Q}\cap\widehat{\mathbb{Z}}$.
    Because $x$ is rational we can write it as $\frac{A}{B}\otimes_t1$ for some
    fraction $A/B$ in lowest terms, and hence $x=A/B$ where now we regard $A\in\widehat{\mathbb{Z}}$
    and note that $A/B$ is still in lowest terms. However $x\in\widehat{\mathbb{Z}}$ implies that
    $x=x/1$ is in lowest terms, so we deduce that $B=1$ and thus $x=A\in\mathbb{Z}$.
\end{proof}

n711.content:
\begin{lemma}
    \label{QHat.rat_join_zHat}
    \lean{QHat.rat_join_zHat}
    \uses{QHat,ZHat.commRing}
    \leanok
    The sum of $\mathbb{Q}$ and $\widehat{\mathbb{Z}}$ in $\widehat{\mathbb{Q}}$ is $\widehat{\mathbb{Q}}$.
    More precisely, every element of $\widehat{\mathbb{Q}}$ can be written as $q+z$ with $q\in\mathbb{Q}$ and $z\in\widehat{\mathbb{Z}}$,
    or more precisely as $q\otimes_t 1+1\otimes_t z$.
\end{lemma}

n712.content:
\begin{proof}
    \uses{QHat.canonicalForm}
    \leanok
    Write $x\in\widehat{\mathbb{Q}}$ as $x=z/N$ in lowest terms. Lift $z_N$ to an integer $t$ and observe
    that $(z-t)_N=0$, hence $z-t=Ny$ for some $y\in\widehat{\mathbb{Z}}$. Now $x=t/N+y\in\mathbb{Q}+\widehat{\mathbb{Z}}$.
\end{proof}

n713.content:
\begin{lemma}
    \label{Qhat.unitsrat_meet_unitszHat}
    \lean{QHat.unitsrat_meet_unitszHat}
    \uses{QHat,ZHat.commRing}
    \leanok
    The intersection of $\mathbb{Q}^\times$ and $\widehat{\mathbb{Z}}^\times$ in $\widehat{\mathbb{Q}}^\times$ is $\mathbb{Z}^\times$.
\end{lemma}

n714.content:
\begin{proof}
    \uses{QHat.lowestTerms,QHat.rat_meet_zHat}
    \leanok
    Clearly the intersection is contained within $\mathbb{Q}\cap\widehat{\mathbb{Z}}=\mathbb{Z}$. If $n\in\mathbb{Z}$ is in $\widehat{\mathbb{Z}}^\times$
    then $n\not=0$ and its inverse $1/n=\pm1/|n|$ is in lowest terms but also in $\widehat{\mathbb{Z}}$,
    and hence $|n|=1$ by uniqueness of lowest term representation.
\end{proof}

n715.content:
\begin{lemma}
    \label{QHat.unitsrat_join_unitszHat}
    \lean{QHat.unitsrat_join_unitszHat}
    \uses{QHat,ZHat.commRing}
    \leanok
    The product of $\mathbb{Q}^\times$ and $\widehat{\mathbb{Z}}^\times$ in $\widehat{\mathbb{Q}}^\times$ is all of $\widehat{\mathbb{Q}}^\times$.
    More precisely, every element of $\widehat{\mathbb{Q}}^\times$ can be written as $qz$ with $q\in\mathbb{Q}^\times$
    and $z\in\widehat{\mathbb{Z}}^\times$.
\end{lemma}

n717.content:
\begin{definition}
    \label{Hurwitz}
    \lean{Hurwitz}
    \leanok
        The Hurwitz quaternions are the set $\mathcal{O}:= \mathbb{Z}\oplus\mathbb{Z}\omega\oplus\mathbb{Z}i\oplus
    \mathbb{Z}i\omega$ (as an abstract abelian group or as a subgroup of the usual quaternions).
    Here $\omega=\frac{-1+(i+j+k)}{2}$ and note that $(i+j+k)^2=-3$.
    We have $\overline{\omega}=\omega^2=-(\omega+1)$. A general quaternion
    $a+bi+cj+dk$ is a Hurwitz quaternion if either $a,b,c,d\in\mathbb{Z}$
    or $a,b,c,d\in\mathbb{Z}+\frac{1}{2}$.
\end{definition}

n718.content:
\begin{lemma}
    \label{Hurwitz.ring}
    \lean{Hurwitz.ring}
    \uses{Hurwitz}
    \leanok
    The Hurwitz quaternions form a ring.
\end{lemma}

n720.content:
\begin{definition}
    \label{Hurwitz.starRing}
    \lean{Hurwitz.starRing}
    \uses{Hurwitz.ring}
    \leanok
    There's a conjugation map (which we'll call "star") from the Hurwitz quaternions to themselves, sending
    integers to themselves and purely imaginary elements like $2\omega+1$ to minus themselves.
    It satisfies $(x^*)^*=x$, $(xy)^*=y^*x^*$ and $(x+y)^*=x^*+y^*$. In particular, the Hurwitz
    quaternions are a "star ring" in the sense of mathlib.
\end{definition}

n721.content:
\begin{definition}
    \label{Hurwitz.norm}
    \lean{Hurwitz.norm}
    \uses{Hurwitz}
    \leanok
    The Hurwitz quaternions come equipped with an integer-valued norm, which is
    $a^2+b^2+c^2+d^2$ on $a+bi+cj+dk$ but needs to be modified a bit to deal with $\omega$.
\end{definition}

n728.content:
\begin{lemma}
    \label{Hurwitz.norm_mul}
    \lean{Hurwitz.norm_mul}
    \uses{Hurwitz.norm}
    \leanok
    The norm of a product is the product of the norms.
\end{lemma}

n730.content:
\begin{lemma}
    \label{Hurwitz.norm_nonneg}
    \lean{Hurwitz.norm_nonneg}
    \uses{Hurwitz.norm}
    \leanok
    The norm of an element is nonnegative.
\end{lemma}

n731.content:
\begin{proof} \leanok
    It's a sum of rational squares.
\end{proof}

n732.content:
\begin{lemma}
    \label{Hurwitz.norm_eq_zero}
    \lean{Hurwitz.norm_eq_zero}
    \uses{Hurwitz.norm}
    \leanok
    The norm of an element is zero if and only if the element is zero.
\end{lemma}

n733.content:
\begin{proof}
    \leanok
    It's a sum of rational squares.
\end{proof}

n734.content:
\begin{lemma}
    \label{Hurwitz.exists_near}
    \lean{Hurwitz.exists_near}
    \uses{Hurwitz.norm}
    \leanok
    Given a ``usual'' quaternion $a=x+yi+zj+wk$ with $x,y,z,w\in\mathbb{R}$,
    there exists a Hurwitz quaternion $q$ such that $N(a-q)<1$.
\end{lemma}

n736.content:
\begin{lemma}
    \label{Hurwitz.quot_rem}
    \lean{Hurwitz.quot_rem}
    \uses{Hurwitz.norm, Hurwitz.exists_near}
    \leanok
    Given two Hurwitz quaternions $a$ and $b$ with $b$ nonzero, there exists
    $q$ and $r$ such that $a=qb+r$ and $N(r)<N(b)$.
\end{lemma}

n737.content:
\begin{proof}
    \leanok
  Let $q$ be the Hurwitz quaternion obtained by applying Lemma~\ref{Hurwitz.exists_near}
  to $a/b := ab^{-1}$; then $N(a/b-q)<1$ and now everything follows after multiplying up.
\end{proof}

n738.content:
\begin{corollary}
    \label{Hurwitz.left_ideal_princ}
    \lean{Hurwitz.left_ideal_princ}
    \uses{Hurwitz.norm}
    \leanok
    All left ideals of $\mathcal{O}$ are principal.
\end{corollary}

n739.content:
\begin{proof}
    \uses{Hurwitz.quot_rem}
    \leanok
    If the ideal is 0, use 0. Otherwise, choose a nonzero element of smallest norm.
\end{proof}

n740.content:
\begin{remark}
    All right ideals are principal too, because there's
    another version of Euclid saying $a=bq+r$.
\end{remark}

n741.content:
\begin{theorem}
    \label{Hurwitz.surjective_pnat_quotient}
    \uses{Hurwitz}
    If $N$ is a positive natural then the obvious map $\mathcal{O}\to\widehat{\mathcal{O}}/N\widehat{\mathcal{O}}$ is surjective.
\end{theorem}

n742.content:
\begin{proof}
    This is just four copies of the surjection $\mathbb{Z}\to\widehat{\mathbb{Z}}/N\widehat{\mathbb{Z}}$.
    Note that this latter map is surjective because $\mathbb{Z}\to\mathbb{Z}/N\mathbb{Z}$ is surjective,
    hence given $z\in\widehat{\mathbb{Z}}$ you can subtract an integer $w$ such
    that $(z-w)_N=0$, so $z-w$ is a multiple of~$N$.
\end{proof}

n743.content:
\begin{lemma}
    \label{HurwitzRatHat.canonicalForm}
    \lean{HurwitzRatHat.canonicalForm}
    \uses{QHat, ZHat, Hurwitz}
    \leanok
    Every element of $\widehat{D}$ can be written as $z/N$ with $z\in\widehat{\mathcal{O}}$ and $N\in\mathbb{N}^+$.
\end{lemma}

n745.content:
\begin{theorem}
    \label{HurwitzRatHat.completed_units}
    \lean{HurwitzRatHat.completed_units}
    \uses{HurwitzRatHat.canonicalForm}
    \leanok
    The group of units of $\widehat{D}$ is $D^\times\widehat{\mathcal{O}}^\times$.
    More precisely, every element of $\widehat{D}^\times$ can be written as a product $\delta u$
    with $\delta\in D^\times$ and $u\in\widehat{\mathcal{O}}^\times$.
\end{theorem}

n747.content:
\begin{lemma}
    \label{MatrixRing.isCentralSimple}
    %\lean{MatrixRing.isCentralSimple}
    %\uses{IsCentralSimple}
    \discussion{47}
    \leanok
    If $n\geq1$ then the $n\times n$ matrices $M_n(K)$ are a central simple algebra over~$K$.
\end{lemma}

n749.content:
\begin{lemma}
    \label{IsCentralSimple.baseChange} % no Lean yet because Lean didn't seem to know L \otimes_K D was a ring
    %\uses{IsCentralSimple}
    If $D$ is a central simple algebra over~$K$ and $L/K$ is a field extension, then $L\otimes_KD$
    is a central simple algebra over~$L$.
\end{lemma}

n750.content:
\begin{proof}
    This is not too hard: it's lemma b of section 12.4 in Peirce's "Associative algebras".
\end{proof}

n751.content:
\begin{definition}
  \label{AutomorphicForm.GLn.IsSmooth}
  \lean{AutomorphicForm.GLn.IsSmooth}
  A function $f:\GL_n(\mathbb{A}_{\mathbb{Q}}^f)\times\GL_n(\mathbb{R})\to\mathbb{C}$ is \emph{smooth}
  if it has the following three properties.

  \begin{enumerate}
    \item $f$ is continuous.
    \item For all $x\in\GL_n(\mathbb{A}_{\mathbb{Q}}^f)$, the function $y\mapsto f(x,y)$ is smooth.
    \item For all $y\in\GL_n(\mathbb{R})$, the function $x\mapsto f(x,y)$ is locally constant.
  \end{enumerate}
\end{definition}

n752.content:
\begin{definition}
  \label{AutomorphicForm.GLn.IsSlowlyIncreasing}
  \lean{AutomorphicForm.GLn.IsSlowlyIncreasing}
  \leanok
  We say that a function $f:\GL_n(\mathbb{R})\to\mathbb{C}$ is \emph{slowly-increasing}
  if there's some real constant $C$ and positive integer $n$ such that $|f(M)|\leq Cs(M)^n$
  for all $M\in\GL_n(\mathbb{R})$.
\end{definition}

n753.content:
\begin{definition}
  \label{AutomorphicForm.GLn.Weight}
  \lean{AutomorphicForm.GLn.Weight}

The \emph{weight} of an automorphic form for $\GL_n/\mathbb{Q}$ can be thought of as a finite-dimensional
continuous complex representation $\rho$ of a maximal compact subgroup of $\GL_n(\mathbb{R})$,
and it's convenient to choose one (they're all conjugate) so we choose $O_n(\mathbb{R})$.
\end{definition}

n754.content:
\begin{definition}
  \label{instLieAlgebraAction}
There is a natural action of the real Lie algebra of $\GL_n(\mathbb{R})$ on the complex vector space of
smooth complex-valued functions on $\GL_n(\mathbb{R})$.
\end{definition}

n755.content:
\begin{definition}
  \label{instComplexLieAlgebraAction}
  \uses{instLieAlgebraAction}

  This extends to is a natural complex Lie algebra action of the complexification of
  the real Lie algebra, on the smooth complex functions on $\GL_n(\mathbb{R})$.

\end{definition}

n756.content:
\begin{definition}
  \label{instUniversalEnvelopingAlgebraAction}
  \uses{instComplexLieAlgebraAction}
By functoriality, we get an action of the universal enveloping algebra of this
complexified Lie algebra on the smooth complex functions.

\end{definition}

n757.content:
\begin{definition}
\label{instCentreAction}
\uses{instUniversalEnvelopingAlgebraAction}
Thus the \emph{centre} $\mathbb{Z}_n$ of this universal enveloping algebra also acts on the smooth
complex functions.

\end{definition}

n760.content:
\begin{lemma} The group $\GL_n(\mathbb{A}_{\mathbb{Q}}^f)$ acts (on the left) on the space of automorphic forms
  for $\GL_n(\mathbb{A}_{\mathbb{Q}})$ by the formula $(g\cdot f)(x,y)=f(xg,y)$.
\end{lemma}

n761.content:
\begin{proof}
  This is obvious. Note that the conjugate of a compact open subgroup is still
  compact and open.
\end{proof}

n762.content:
\begin{lemma} This function is well-defined, i.e., it sends a $U$-invariant form to
  a $U$-invariant form which is independent of the choice of $g_i$.
\end{lemma}

n764.content:
\begin{definition}
  \label{IsFractionRing.stabilizerHom}
  \lean{IsFractionRing.stabilizerHom}
  Choose $g\in D_Q$. Then the action of $g$ on $B$ gives us an induced
  $A/P$-algebra automorphism of $B/Q$ which extends to a $K$-algebra automorphism $\phi(g)$ of $L$.
  This construction $g\mapsto \phi(g)$ defines a group homomorphism from $D_Q$
  to $\Aut(L/K)$ (all the proofs implicit in the definition here are straightforward).
  \mathlibok
\end{definition}

n765.content:
\begin{theorem}
  \label{IsFractionRing.stabilizerHom_surjective}
  \lean{IsFractionRing.stabilizerHom_surjective}
  \uses{IsFractionRing.stabilizerHom}
  \mathlibok
  The map $g\mapsto \phi_g$ from $D_Q$ to $\Aut(L/K)$ defined above is surjective.
\end{theorem}

n766.content:
\begin{definition}
  \label{MulSemiringAction.charpoly}
  \lean{MulSemiringAction.charpoly}
  \mathlibok
  If $b\in B$ then define the \emph{characteristic polynomial}
  $F_b(X) \in B[X]$ of $b$ to be $\prod_{g\in G}(X-g\cdot b)$.
\end{definition}

n769.content:
\begin{lemma}
  \label{Algebra.IsInvariant.charpoly_mem_lifts}
  \lean{Algebra.IsInvariant.charpoly_mem_lifts}
  \uses{MulSemiringAction.charpoly}
  \mathlibok
  $F_b$ is the lift of some monic polynomial $M_b$ in $A[X]$.
\end{lemma}

n770.content:
\begin{proof}
  \mathlibok
  The coefficients of $F_b$ are $G$-invariant, and thus lie in the image of $A$.
\end{proof}

n773.content:
\begin{lemma}
  \label{fixed_of_fixed1_aux1}
  \mathlibok
  There exist elements $a,b \in B$, with $a \notin Q$ and $a$ in the image of $A$ such that
  for all $g\in G$,
  \begin{itemize}
    \item If $g \cdot Q = Q$, then $g \cdot b \equiv a \pmod{Q}$.
    \item If $g \cdot Q \neq Q$, then $g \cdot b \equiv 0 \pmod{Q}$.
  \end{itemize}
\end{lemma}

n775.content:
\begin{lemma}
  \label{fixed_of_fixed1_aux2}
  \mathlibok
  Let $b_0 \in B$.
  Suppose that the image of $b_0$ in the quotient $B/Q$ is fixed by the stabilizer subgroup
  $D_Q$.
  Then there exist elements $a,b \in B$, with $a\notin Q$ and $a$ in the image of $A$ such that
  for all $g\in G$,
  \begin{itemize}
    \item If $g \cdot Q = Q$, then $g \cdot b \equiv ab_0 \pmod{Q}$.
    \item If $g \cdot Q \neq Q$, then $g \cdot b \equiv 0 \pmod{Q}$.
  \end{itemize}
\end{lemma}

n777.content:
\begin{theorem}
  \label{FixedPoints.toAlgAut_surjective}
  \lean{FixedPoints.toAlgAut_surjective}
  Let $H$ be a finite group acting on a field $F$ by field automorphisms.
  Then the map $H \to \Aut(F/F^H)$ is surjective.
  \mathlibok
\end{theorem}

n778.content:
\begin{proof}
  This is a general fact of Galois theory and was already in mathlib.
  \mathlibok
\end{proof}

n779.content:
\begin{proposition}
  \label{fixed_of_fixed1}
  \uses{IsFractionRing.stabilizerHom}
  \mathlibok
  Let $b_0 \in B/Q$.
  Suppose that $b_0$ is fixed by the stabilizer subgroup $D_Q$.
  Then $b_0$ is fixed by $\Aut(L/K)$.
\end{proposition}

n781.content:
\begin{lemma}
  \label{IsAlgebraic.exists_smul_eq_mul}
  \lean{IsAlgebraic.exists_smul_eq_mul}
  \mathlibok
  If $R/S$ is an algebraic extension of integral domains, then any fraction $a/b$ with $a,b\in R$
  can be written as $c/d$ with $c\in R$ and $d\in S$.
\end{lemma}

n782.content:
\begin{proof}
  If $f\in S[X]$ satisfies $f(b)=0$, then $f(0)\in S$ is a multiple of $b$.
  If $f(0)=bx\in S$, then $a/b=(ax)/(bx)$ as desired.
  \mathlibok
\end{proof}

n783.content:
\begin{proposition}
  \label{fixed_of_fixed2}
  \mathlibok
  Let $x \in L$.
  Suppose that $x$ is fixed by the stabilizer subgroup $D_Q$.
  Then $x$ is fixed by the automorphism group $\Aut(L/K)$.
\end{proposition}

n784.content:
\begin{proof}
  \uses{fixed_of_fixed1, Algebra.IsInvariant.isIntegral,
    IsAlgebraic.exists_smul_eq_mul}
  Since $(B/Q)/(A/Q)$ is algebraic by~\ref{Algebra.IsInvariant.isIntegral},
  ~\ref{IsAlgebraic.exists_smul_eq_mul} let's us write $x=b/a$ for $b \in B/Q$ and $a \in A/P$.
  Then $b$ is fixed by the stabilizer subgroup $D_Q$, and it suffices to show that
  $b$ is fixed by the automorphism group $\Aut(L/K)$.
  But this is exactly~\ref{fixed_of_fixed1}.
  \mathlibok
\end{proof}

n786.content:
\begin{theorem}
  \label{NumberField.instCompactSpaceAdicCompletionIntegers}
  \lean{NumberField.instCompactSpaceAdicCompletionIntegers}
  \discussion{451}
  \leanok
  If $K$ is a number field and $v$ is a nonzero prime ideal of the integers of $K$,
  then the integers of $K_v$ is a compact open subgroup.
\end{theorem}

n788.content:
\begin{theorem}
  \lean{NumberField.AdeleRing.locallyCompactSpace}
  \label{NumberField.AdeleRing.locallyCompactSpace}
  \uses{NumberField.instCompactSpaceAdicCompletionIntegers}
  \discussion{253}
  \leanok
  The adeles of a number field are locally compact.
\end{theorem}

n789.content:
\begin{proof}
  The adeles of a number field are a product of the finite adeles and the infinite adeles
  so it suffices to prove that the finite and infinite adeles are locally compact.
  The infinite adeles are just isomorphic to $\mathbb{R}^n$ as a topological space, so they're certainly
  locally compact. As for the finite adeles,
  the mathlib theorem {\tt RestrictedProduct.locallyCompactSpace\_of\_addGroup}
  says that a restricted product of locally compact additive groups with respect to open compact
  subgroups is locally compact, so this reduces us the previous result.
\end{proof}

n790.content:
\begin{lemma}
  \label{IsDedekindDomain.HeightOneSpectrum.valuation_comap}
  \lean{IsDedekindDomain.HeightOneSpectrum.valuation_comap}
  \leanok
  If $i:K\to L$ denotes the inclusion then for $k\in K$ we have
  $e\times w(i(k))=v(k)$, where $e$ is the ramification index of $w/v$
  (recall that valuations here are written additively, unlike in mathlib).
\end{lemma}

n792.content:
\begin{definition}
  \lean{IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom}
  \label{IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom}
  \uses{IsDedekindDomain.HeightOneSpectrum.valuation_comap}
  \leanok
  There's a natural ring map $K_v\to L_w$ extending the map $K\to L$.
  It is defined by completing
  the inclusion $K\to L$ at the finite places $v$ and $w$ (which can be done
  because the previous lemma shows that the map is uniformly continuous for the $v$-adic
  and $w$-adic topologies).
\end{definition}

n793.content:
\begin{lemma}
  \lean{IsDedekindDomain.HeightOneSpectrum.Extension.valued_adicCompletionSemialgHom}
  \label{IsDedekindDomain.HeightOneSpectrum.Extension.valued_adicCompletionSemialgHom}
  \uses{IsDedekindDomain.HeightOneSpectrum.valuation_comap,
  IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom}
  \leanok
  If $i_v:K_v\to L_w$ denotes the map of the previous definition
  then for $x\in K_v$ we have
  $e\times w(i(k))=v(k)$, where $e$ is the ramification index of $w/v$.
\end{lemma}

n795.content:
\begin{lemma}
  \lean{IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom_image_adicCompletionIntegers}
  \label{IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom_image_adicCompletionIntegers}
  \uses{IsDedekindDomain.HeightOneSpectrum.Extension.valued_adicCompletionSemialgHom}
  \leanok
  The map $i_v:K_v\to L_w$ sends the integer ring $A_v$ into $B_w$.
\end{lemma}

n796.content:
\begin{proof}
  \leanok
  The integer ring is defined by $v\geq0$ (or $v\leq 1$ in mathlib, which uses multiplicative
  valuations) so the result follows from \ref{IsDedekindDomain.HeightOneSpectrum.Extension.valued_adicCompletionSemialgHom}.
\end{proof}

n797.content:
\begin{theorem}
  \lean{IsDedekindDomain.HeightOneSpectrum.adicCompletion.instIsModuleTopology}
  \label{IsDedekindDomain.HeightOneSpectrum.adicCompletion.instIsModuleTopology}
  \uses{IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom}
  \leanok
  \discussion{326}
  Giving $L_w$ the $K_v$-algebra structure coming from the natural map $K_v\to L_w$,
  the $w$-adic topology on $L_w$ is the $K_v$-module topology.
\end{theorem}

n799.content:
\begin{lemma}
  \lean{IsDedekindDomain.HeightOneSpectrum.Extension.finite}
  \label{IsDedekindDomain.HeightOneSpectrum.Extension.finite}
  \leanok
  There are only finitely many primes $w$ of $B$ lying above $v$.
\end{lemma}

n800.content:
\begin{proof}
  \leanok
  This is a standard fact about Dedekind domains. The key input is
  mathlib's theorem {\tt primesOver\_finite}.
\end{proof}

n801.content:
\begin{definition}
  \lean{IsDedekindDomain.HeightOneSpectrum.adicCompletion.semialgHomPi}
  \label{IsDedekindDomain.HeightOneSpectrum.adicCompletion.semialgHomPi}
  \uses{IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom}
  \leanok
  The product of the maps $K_v\to L_w$ for $w|v$ is a natural ring map $K_v\to\prod_{w|v}L_w$
  lying over $K\to L$.
\end{definition}

n802.content:
\begin{theorem}
  \lean{IsDedekindDomain.HeightOneSpectrum.adicCompletion.baseChangeAlgEquiv}
  \label{IsDedekindDomain.HeightOneSpectrum.adicCompletion.baseChangeAlgEquiv}
  \uses{IsDedekindDomain.HeightOneSpectrum.adicCompletion.semialgHomPi,
  IsDedekindDomain.HeightOneSpectrum.Extension.finite}
  \leanok
  The induced $L$-algebra homomorphism $L\otimes_KK_v\to\prod_{w|v}L_w$ is an
  isomorphism of rings.
\end{theorem}

n804.content:
\begin{theorem}
  \label{IsDedekindDomain.HeightOneSpectrum.adicCompletion.instIsModuleTopologyPi}
  \lean{IsDedekindDomain.HeightOneSpectrum.adicCompletion.instIsModuleTopologyPi}
  \uses{IsDedekindDomain.HeightOneSpectrum.adicCompletion.instIsModuleTopology}
  \leanok
  For $v$ fixed, the product topology on $\prod_{w|v}L_w$ is the $K_v$-module
  topology.
\end{theorem}

n806.content:
\begin{theorem}
  \label{IsDedekindDomain.HeightOneSpectrum.adicCompletion.baseChangeContinuousAlgEquiv}
  \lean{IsDedekindDomain.HeightOneSpectrum.adicCompletion.baseChangeContinuousAlgEquiv}
  \uses{IsDedekindDomain.HeightOneSpectrum.adicCompletion.instIsModuleTopologyPi}
  If we give $L\otimes_KK_v$ the $K_v$-module topology then the $L$-algebra isomorphism
  $L\otimes_K K_v\cong\prod_{w|v}L_w$ is also a homeomorphism.
\end{theorem}

n808.content:
\begin{theorem}
  \lean{IsDedekindDomain.HeightOneSpectrum.range_baseChange_comp_tensorAdicCompletionTo_eq_pi}
  \label{IsDedekindDomain.HeightOneSpectrum.range_baseChange_comp_tensorAdicCompletionTo_eq_pi}
  \uses{IsDedekindDomain.HeightOneSpectrum.adicCompletion.baseChangeAlgEquiv}
  \leanok
  The isomorphism $L\otimes_KK_v\to\prod_{w|v}L_w$ induces an isomorphism
  $B\otimes_AA_v\to \prod_{w|v}B_w$
  for all $v$ in the height one spectrum of $A$.
\end{theorem}

n810.content:
\begin{definition}
  \label{IsDedekindDomain.FiniteAdeleRing.mapSemialgHom}
  \lean{IsDedekindDomain.FiniteAdeleRing.mapSemialgHom}
  \uses{IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom,
  IsDedekindDomain.HeightOneSpectrum.Extension.adicCompletionSemialgHom_image_adicCompletionIntegers}
  \leanok
  There's a natural ring homomorphism
  $\mathbb{A}_{A,K}^\infty\to\mathbb{A}_{B,L}^\infty$ lying over $K\to L$.
\end{definition}

n811.content:
\begin{theorem}
  \label{IsDedekindDomain.FiniteAdeleRing.baseChangeAlgEquiv}
  \lean{IsDedekindDomain.FiniteAdeleRing.baseChangeAlgEquiv}
  \uses{IsDedekindDomain.HeightOneSpectrum.range_baseChange_comp_tensorAdicCompletionTo_eq_pi,
    RestrictedProduct.relabelIso,
    IsDedekindDomain.FiniteAdeleRing.baseChangeIntegralAlgEquiv,
    IsDedekindDomain.AKLB.tensorProduct_module_algEquiv}
  \leanok
  \discussion{243}
  This natural map $L\otimes_K\mathbb{A}_{A,K}^\infty\to\mathbb{A}_{B,L}^\infty$ is an isomorphism.
\end{theorem}

n812.content:
\begin{theorem}
  \label{IsDedekindDomain.FiniteAdeleRing.baseChangeContinuousAlgEquiv}
  \lean{IsDedekindDomain.FiniteAdeleRing.baseChangeContinuousAlgEquiv}
  \uses{IsDedekindDomain.HeightOneSpectrum.range_baseChange_comp_tensorAdicCompletionTo_eq_pi}
  \leanok
The induced $L$-algebra morphism
  $L\otimes_K\mathbb{A}_{A,K}^\infty\to\mathbb{A}_{B,L}^\infty$ is a topological isomorphism.
\end{theorem}

n813.content:
\begin{lemma}
  \label{IsDedekindDomain.dvd_norm}
  If $0\not=b\in B$ then there exists $0\not=a\in A$ such that $b$ divides
  the image of $a$ in $B$.
\end{lemma}

n816.content:
\begin{corollary}
  \label{IsDedekindDomain.AKLB.surjective_tensorProduct_map}
  \uses{IsDedekindDomain.dvd_norm}
  The $A$-bilinear map $B\times K\to L$ sending $(b,k)$ to $bk$ is surjective.
\end{corollary}

n817.content:
\begin{proof} Given $\lambda\in L$ write it as $n/d$ with $0\not=d\in B$. Choose $0\not=a\in A$
  and $b\in B$ with $db=a$ and then note $\lambda=nb/a=nb\times a^{-1}$.
\end{proof}

n818.content:
\begin{corollary}
  \label{IsDedekindDomain.FiniteAdeleRing.tensorProduct_algEquiv}
  \uses{IsDedekindDomain.dvd_norm}
  The natural map $B\otimes_AK\to L$ is a $B$-algebra isomorphism.
\end{corollary}

n820.content:
\begin{corollary}
  \label{IsDedekindDomain.AKLB.tensorProduct_module_algEquiv}
  %%% \uses{IsDedekindDomain.FiniteAdeleRing.baseChangeAlgEquiv} -- uncomment to break leanblueprint
  \lean{IsDedekindDomain.linearEquivTensorProductModule}
  \leanok
  If $M$ is any $K$-module then the canonical map $B\otimes_A M\to L\otimes_K M$
  is an isomorphism.
\end{corollary}

n821.content:
\begin{proof}
  \leanok
  We can factor this map as $B\otimes_AM\cong B\otimes_A(K\otimes_KM)\cong
  (B\otimes_A K)\cong_KM\to L\otimes_KM$ and we just showed that the latter map was an
  isomorphism.
\end{proof}

n824.content:
\begin{theorem}
  \label{pi_tensorProduct_of_finitePresentation}
  If $R$ is a commutative ring, if $M$ is a finitely presented $R$-module
  and if $N_i$ are a collection of $R$-modules, then the canonical map
  $M\otimes_R\prod_i N_i\to\prod_i(M\otimes_R N_i)$ is an isomorphism.
\end{theorem}

n826.content:
\begin{corollary}
  \label{IsDedekindDomain.pi_tensorProduct}
  \uses{IsDedekindDomain.AKLB.finitePresentation,pi_tensorProduct_of_finitePresentation}
  If $S$ is a finite set of nonzero primes of $A$ then the natural map
  $B\otimes((\prod_{v\in S}K_v)\times(\prod_{v\notin S}A_v))\to
  (\prod_{v\in S}(B\otimes_AK_v))\times(\prod_{v\notin S}(B\otimes_AA_v))$
  is an isomorphism.
\end{corollary}

n827.content:
\end{corollary}
\begin{proof} Follows from the previous two theorems.
\end{proof}

n828.content:
\begin{corollary}
  \label{IsDedekindDomain.FiniteAdeleRing.IntegraltensorProductAlgEquiv_aux1}
  \uses{IsDedekindDomain.pi_tensorProduct}
  The natural map $B\otimes_A\mathbb{A}_K^\infty\to R$ is a $B$-algebra isomorphism.
\end{corollary}

n829.content:
\begin{proof} This follows from the previous corollary and the fact that
  tensor products commute with filtered colimits.
\end{proof}

n830.content:
\begin{definition}
  \label{RestrictedProduct.relabelIso}
  Let $V$ and $W$ be index sets, and let $f:W\to V$ be a map with finite fibres.
  Let $X_v$ be sets, with subsets $C_v$, let $Y_w$ be sets with subsets $D_w$,
  and say for all $v\in V$ we're given a bijection $X_v\to\prod_{w|f(w)=v}Y_w$,
  identifying $C_v$ with $\prod_{w:f(w)=v}D_w$. Then there's an induced bijection between
  the restricted products $\prod'_v(X_v,C_v)$ and $\prod'_w(Y_w,D_w)$.
\end{definition}

n831.content:
\begin{corollary}
  \label{IsDedekindDomain.FiniteAdeleRing.IntegraltensorProductAlgEquiv_aux2}
  \uses{RestrictedProduct.relabelIso}
  The ring $R$ introduced above (the restricted
  product of the $B\otimes_A K_v$ with respect to the $B\otimes_A A_v$)
  is isomorphic to $\mathbb{A}_L$.
\end{corollary}

n832.content:
\begin{proof} Let $V$ be the finite places of $K$ and $W$ the finite places of $L$,
