n844.content:
\begin{theorem}
  \label{NumberField.InfinitePlace.Completion.denseRange_algebraMap_subtype_pi}
  \lean{NumberField.InfinitePlace.Completion.denseRange_algebraMap_subtype_pi}
  \leanok
  Let $S$ be a set of infinite places of $K$. The image of $K$ under the embedding
  $K\hookrightarrow (K_v)_{v\in S}; k \mapsto (k)_v$ is dense in the product topology.
\end{theorem}

n846.content:
\begin{theorem}
  \label{NumberField.InfinitePlace.Completion.finrank_pi_eq_finrank_tensorProduct}
  \lean{NumberField.InfinitePlace.Completion.finrank_pi_eq_finrank_tensorProduct}
  For a fixed infinite place $v$ of $K$, we have
  $\text{dim}_{K_v} \prod_{w\mid v} L_w = \text{dim}_{K_v} L\otimes_K K_v$.
\end{theorem}

n847.content:
\begin{definition}
  \label{NumberField.InfinitePlace.Completion.piExtension}
  \lean{NumberField.InfinitePlace.Completion.piExtension}
  \leanok
  Let $v$ be an infinite place of $K$. There is a continuous $K$-algebra homomorphism
  $K_v \to \prod_{w\mid v}L_w$, whose restriction to $K$ corresponds to the global embedding
  of $K$ into $(L_w)_w$.
\end{definition}

n848.content:
\begin{definition}
  \label{NumberField.InfinitePlace.Completion.baseChange}
  \lean{NumberField.InfinitePlace.Completion.baseChange}
  \leanok
  \uses{NumberField.InfinitePlace.Completion.piExtension}
  Let $v$ be an infinite place of $K$. There is a natural $L$-algebra homomorphism
  $L\otimes_K K_v \to \prod_{w\mid v}L_w$, whose restriction to $1\otimes_K K_v$ corresponds to
  the map in~\ref{NumberField.InfinitePlace.Completion.piExtension}.
\end{definition}

n849.content:
\begin{theorem}
  \label{NumberField.InfinitePlace.Completion.baseChange_surjective}
  \lean{NumberField.InfinitePlace.Completion.baseChange_surjective}
  \leanok
  \uses{NumberField.InfinitePlace.Completion.denseRange_algebraMap_subtype_pi}
  For a fixed infinite place $v$ of $K$, the map $L\otimes_K K_v \to\prod_{w\mid v}L_w$ is
  surjective.
\end{theorem}

n851.content:
\begin{theorem}
  \label{NumberField.InfinitePlace.Completion.baseChange_injective}
  \lean{NumberField.InfinitePlace.Completion.baseChange_injective}
  \leanok
  \uses{NumberField.InfinitePlace.Completion.finrank_pi_eq_finrank_tensorProduct}
  For a fixed infinite place $v$ of $K$, the map $L\otimes_K K_v \to\prod_{w\mid v}L_w$ is
  injective.
\end{theorem}

n853.content:
\begin{theorem}
  \label{NumberField.InfinitePlace.Completion.instIsModuleTopologyValEqComapAlgebraMap_fLT}
  \lean{NumberField.InfinitePlace.Completion.instIsModuleTopologyValEqComapAlgebraMap_fLT}
  \leanok
  If $w \mid v$ is an infinite place of $L$ lying above the infinite place $v$ of $K$, then
  $L_w$ has the $K_v$-module topology.
\end{theorem}

n854.content:
\begin{proof}
  Because $L_w$ is a finite-dimensional normed $K_v$ vector space, there exists a $K_v$-linear
  linear homeomorphism $L_w \cong K_v^n$, from which $L_w$ has the $K_v$-module topology.
\end{proof}

n855.content:
\begin{theorem}
  \label{NumberField.InfinitePlace.Completion.baseChangeEquiv}
  \lean{NumberField.InfinitePlace.Completion.baseChangeEquiv}
  \leanok
  \uses{NumberField.InfinitePlace.Completion.baseChange,
    NumberField.InfinitePlace.Completion.baseChange_surjective,
    NumberField.InfinitePlace.Completion.baseChange_injective,
    NumberField.InfinitePlace.Completion.instIsModuleTopologyValEqComapAlgebraMap_fLT}
  Let $v$ be an infinite place of $K$. There is a natural $L$-algebra homeomorphism
  $L\otimes_K K_v \cong_L \prod_{w\mid v}L_w$, whose restriction to $1\otimes_K K_v$ corresponds to
  the map in~\ref{NumberField.InfinitePlace.Completion.piExtension}.
\end{theorem}

n856.content:
\begin{proof}
  The map in~\ref{NumberField.InfinitePlace.Completion.baseChange} is an $L$-algebra
  isomorphism by Theorem~\ref{NumberField.InfinitePlace.Completion.baseChange_surjective}
  and Theorem~\ref{NumberField.InfinitePlace.Completion.baseChange_injective}.
  Every $K_v$-algebra isomorphism between two $K_v$-module topological spaces is a homeomorphism.
  Since the $L$-algebra isomorphism of
  Definition~\ref{NumberField.InfinitePlace.Completion.baseChange} can equivalently be viewed as
  a $K_v$-algebra isomorphism, it is also a homeomorphism.
\end{proof}

n857.content:
\begin{theorem}
  \label{NumberField.InfinitePlace.Completion.piEquiv}
  \lean{NumberField.InfinitePlace.Completion.piEquiv}
  \leanok
  \uses{NumberField.InfinitePlace.Completion.baseChangeEquiv}
  Let $v$ be an infinite place of $K$. There is a natural $K_v$-linear homeomorphism
  $K_v^{[L:K]} \cong_{K_v} \prod_{w\mid v}L_w$.
\end{theorem}

n858.content:
\begin{proof}
  Compose the $K_v$-linear isomorphism $K_v^{[L:K]} \cong \prod_{w\mid v}L_w$ with the $K_v$-linear
  version of base change~\ref{NumberField.InfinitePlace.Completion.baseChangeEquiv} to get the
  isomorphism in the statement.
  Since both sides have the $K_v$-module topology, then this is also a homeomorphism.
\end{proof}

n859.content:
\begin{theorem}
  \label{NumberField.InfiniteAdeleRing.piEquiv}
  \lean{NumberField.InfiniteAdeleRing.piEquiv}
  \leanok
  \uses{NumberField.InfinitePlace.Completion.piEquiv}
  There is a natural $K_{\infty}$-linear homeomorphism
  $K_{\infty}^{[L:K]} \cong_{K_{\infty}} L_{\infty}$.
\end{theorem}

n862.content:
\begin{proof}
  Since $L_{\infty}$ is homeomorphic to a finite product of $K_{\infty}$ as a $K_{\infty}$-vector
  space, it has the $K_{\infty}$-module topology.
\end{proof}

n863.content:
\begin{theorem}
  \label{NumberField.InfiniteAdeleRing.baseChangeAlgEquiv}
  \lean{NumberField.InfiniteAdeleRing.baseChangeAlgEquiv}
  \leanok
  \uses{NumberField.InfinitePlace.Completion.baseChangeEquiv}
  There is a natural $L$-algebra isomorphism
  $L \otimes_K K_{\infty} \cong_L L_{\infty}$.
\end{theorem}

n865.content:
\begin{theorem}
  \label{NumberField.InfiniteAdeleRing.baseChangeEquiv}
  \lean{NumberField.InfiniteAdeleRing.baseChangeEquiv,
    NumberField.InfiniteAdeleRing.instIsModuleTopology_fLT}
  \leanok
  \uses{NumberField.InfiniteAdeleRing.baseChangeAlgEquiv}
  If $K\to L$ is a ring homomorphism between two number fields then there is a natural isomorphism
  (both topological and algebraic) $L\otimes_KK_\infty\cong L_\infty$.
\end{theorem}

n866.content:
\begin{proof}
  Since both sides of the $L$-algebra isomorphism
  in~\ref{NumberField.InfiniteAdeleRing.baseChangeAlgEquiv} have the $K_{\infty}$-module topology,
  and since the isomorphism can equivalently be viewed as a $K_{\infty}$-linear isomorphism,
  it is also a homeomorphism.
\end{proof}

n867.content:
\begin{theorem}
  \label{NumberField.AdeleRing.baseChangeEquiv}
  \lean{NumberField.AdeleRing.baseChangeEquiv}
  \leanok
  \uses{NumberField.InfiniteAdeleRing.baseChangeEquiv,
  IsDedekindDomain.FiniteAdeleRing.baseChangeAlgEquiv}
  If $K\to L$ is a ring homomorphism between two number fields then there is a natural isomorphism
  (both topological and algebraic) $L\otimes_K\mathbb{A}_K\cong\mathbb{A}_L$.
\end{theorem}

n869.content:
\begin{theorem}
  \label{NumberField.AdeleRing.baseChange_moduleTopology}
  \lean{NumberField.AdeleRing.instIsModuleTopology}
  \leanok
  \uses{NumberField.AdeleRing.baseChangeEquiv}
  If $K\to L$ is a ring homomorphism between two number fields then the topology on $\mathbb{A}_L$
  is the $\mathbb{A}_K$-module topology, where the module structure comes from the
  natural map $\mathbb{A}_K\to\mathbb{A}_L$.
\end{theorem}

n870.content:
\begin{proof}
  \leanok
  Indeed $\mathbb{A}_L\cong L\otimes_K\mathbb{A}_K$ is a homeomorphism, and
  the right hand side has the $\mathbb{A}_K$-module topology.
\end{proof}

n871.content:
\begin{theorem}
  \lean{Rat.AdeleRing.zero_discrete}
  \label{Rat.AdeleRing.zero_discrete}
  \leanok
  There's an open subset of $\mathbb{A}_{\mathbb{Q}}$ whose intersection with $\mathbb{Q}$ is $\{0\}$.
\end{theorem}

n872.content:
\begin{proof}
  Use $\prod_p{\mathbb{Z}_p}\times(-1,1)$. Any rational $q$ in this set is a $p$-adic
  integer for all primes $p$ and hence (writing it in lowest terms as $q=n/d$)
  satisfies $p\nmid d$, meaning that $d=\pm1$ and thus $q\in\mathbb{Z}$. The fact
  that $q\in(-1,1)$ implies $q=0$.
\end{proof}

n873.content:
\begin{theorem}
  \lean{NumberField.AdeleRing.zero_discrete}
  \label{NumberField.AdeleRing.zero_discrete}
  \uses{Rat.AdeleRing.zero_discrete,NumberField.AdeleRing.baseChangeEquiv}
  \leanok
  There's an open subset of $\mathbb{A}_{K}$ whose intersection with $K$ is $\{0\}$.
\end{theorem}

n874.content:
\begin{proof}
  By a previous result, we have $\mathbb{A}_K=K\otimes_{\mathbb{Q}}\mathbb{A}_{\mathbb{Q}}$.
  Choose a basis of $K/\mathbb{Q}$; then $K$ can be identified with $\mathbb{Q}^n\subseteq(\mathbb{A}_{\mathbb{Q}})^n$
  and the result follows from the previous theorem.
\end{proof}

n875.content:
\begin{theorem}
  \lean{NumberField.AdeleRing.discrete}
  \label{NumberField.AdeleRing.discrete}
  \uses{NumberField.AdeleRing.zero_discrete}
  \leanok
  The additive subgroup $K$ of $\mathbb{A}_K$ is discrete.
\end{theorem}

n876.content:
\begin{proof}
  If $x\in K$ and $U$ is the open subset in the previous lemma, then
  it's easily checked that $K\cap U=\{0\}$ implies $K\cap (U+x)=\{x\}$,
  and $U+x$ is open.
\end{proof}

n880.content:
\begin{proof}
  We proceed as in the discreteness proof above, by reducing to $\mathbb{Q}$. As before, choosing
  a $\mathbb{Q}$-basis of $K$ gives us $\mathbb{A}_K/K\cong(\mathbb{A}_{\mathbb{Q}}/\mathbb{Q})^n$ so the result follows from
  the previous theorem.
\end{proof}

n881.content:
\begin{definition}
  \label{MeasureTheory.addEquivAddHaarChar}
  \lean{MeasureTheory.addEquivAddHaarChar}
  \leanok
  If $A$ is a locally compact topological additive abelian group,
  if $\mu$ is a regular Haar measure on $A$, and if $\phi:A\to A$ is an
  additive homeomorphism, then we let $d_A(\phi)$ denote the unique positive
  real number such that $\mu(X)=d_A(\phi)(\phi_*\mu)(X)$ for any Borel set~$X$.
\end{definition}

n882.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_eq}
  \lean{MeasureTheory.addEquivAddHaarChar_eq}
  \uses{MeasureTheory.addEquivAddHaarChar}
  \discussion{508}
  \leanok
  $d_A(\phi)$ is independent of choice of regular Haar measure.
\end{lemma}

n883.content:
\begin{proof}
  \leanok
  If $\mu'$ is a second choice then $\mu'=\lambda\mu$ for some
  positive real $\lambda$, and the $\lambda$s on each side of
  $\mu'(X)=d_A(\phi)(\phi_*\mu')(X)$ cancel.
\end{proof}

n884.content:
\begin{lemma}
  \lean{MeasureTheory.addEquivAddHaarChar_smul_map}
  \label{MeasureTheory.addEquivAddHaarChar_smul_map}
  \uses{MeasureTheory.addEquivAddHaarChar_eq}
  \leanok
  If $\mu$ is any regular Haar measure on $A$ then
  $d_A(\phi)(\phi_*\mu) = \mu.$
\end{lemma}

n885.content:
\begin{proof}
  \leanok
  This is a restatement of the previous result.
\end{proof}

n886.content:
\begin{corollary}
  \lean{MeasureTheory.addEquivAddHaarChar_smul_eq_comap}
  \label{MeasureTheory.addEquivAddHaarChar_comap}
  \uses{MeasureTheory.addEquivAddHaarChar_smul_map}
  \leanok
  If $\mu$ is any regular Haar measure on $A$ then
  $d_A(\phi)\mu = \phi^*\mu.$
\end{corollary}

n887.content:
\begin{proof}
  \leanok
  This follows from lemma~\ref{MeasureTheory.addEquivAddHaarChar_smul_map}
  applied to the regular Haar measure $\phi^*\mu$ and the fact that $\phi_*\phi^*\mu=\mu$.
\end{proof}

n888.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_smul_preimage}
  \lean{MeasureTheory.addEquivAddHaarChar_smul_preimage}
  \uses{MeasureTheory.addEquivAddHaarChar}
  \discussion{509}
  \leanok
  If $X$ is a Borel set then $\mu(X)=d_A(\phi)\mu(\phi^{-1}X)$.
\end{lemma}

n889.content:
\begin{proof}
  \leanok
  \uses{MeasureTheory.addEquivAddHaarChar_smul_map}
  This follows immediately from lemma~\ref{MeasureTheory.addEquivAddHaarChar_smul_map}
  and the definition of the pushforward of a measure.
\end{proof}

n890.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_smul_integral_map}
  \lean{MeasureTheory.addEquivAddHaarChar_smul_integral_map}
  \uses{MeasureTheory.addEquivAddHaarChar}
  \discussion{510}
  \leanok
  If $f:A\to\mathbb{R}$ is a Borel measurable function then
  $d_A(\phi)\int f(x)d\phi_*\mu(x)=\int f(x)d\mu(x)$.
\end{lemma}

n892.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_smul_integral_comap}
  \lean{MeasureTheory.integral_comap_eq_addEquivAddHaarChar_smul}
  \uses{MeasureTheory.addEquivAddHaarChar_comap}
  \leanok
  If $f:A\to\mathbb{R}$ is a Borel measurable function then
  $d_A(\phi)\int f(x)d\mu(x)=\int f(x)d\phi^*\mu(x)$.
\end{lemma}

n897.content:
\begin{proof}
  \leanok
  \uses{MeasureTheory.addEquivAddHaarChar_smul_preimage}
  Here's one way: it suffices to prove that
  $d_A(\phi\circ\psi)(\phi\circ\psi)_*\mu=d_A(\phi)d_A(\psi)(\phi\circ\psi)_*\mu$
  (because there exists a compact set with positive finite measure)
  and using lemma~\ref{MeasureTheory.addEquivAddHaarChar_smul_map}
  and the fact that $(\phi\circ\psi)_*\mu=\phi_*(\psi_*\mu)$
  one can simplify both sides to $\mu$.
\end{proof}

n898.content:
\begin{definition}
  \label{MeasureTheory.ringHaarChar}
  \lean{MeasureTheory.ringHaarChar}
  \uses{MeasureTheory.addEquivAddHaarChar,MeasureTheory.addEquivAddHaarChar_refl,
  MeasureTheory.addEquivAddHaarChar_trans}
  \leanok
  We define $\delta_R(u)$ (or just $\delta(u)$ when the ring $R$ is clear) to be $d_R(\ell_u)$.
\end{definition}

n899.content:
\begin{lemma}
  \label{MeasureTheory.ringHaarChar_mul_integral}
  \lean{MeasureTheory.ringHaarChar_mul_integral}
  \uses{MeasureTheory.ringHaarChar}
  \leanok
  \discussion{514}
  If $f:R\to\mathbb{R}$ is a Borel measurable function and $u\in R^\times$ then
  $\delta_R(u)\int f(ux)d\mu(x)=\int f(x)d\mu(x)$.
\end{lemma}

n901.content:
\begin{lemma}
  \label{MeasureTheory.ringHaarChar_mul_volume}
  \lean{MeasureTheory.ringHaarChar_mul_volume}
  \uses{MeasureTheory.ringHaarChar,MeasureTheory.addEquivAddHaarChar_smul_preimage}
  \leanok
  \discussion{515}
  If $X$ is a Borel subset of $R$ and $r\in R^\times$ then $\mu(rX)=\delta_R(r)\mu(X)$.
\end{lemma}

n906.content:
\begin{proof}
  \uses{MeasureTheory.ringHaarChar_mul_volume}
  \leanok
  Take $\mu$ to be Lebesgue measure and $X=[0,1]$.
We have $\delta(u)=\mu(uX)$. If $u>0$ then $u[0,1]=[0,u]$ which has measure $u=|u|$,
and if $u<0$ then $u*[0,1]=[u,0]$ which has measure $-u=|u|$.
\end{proof}

n908.content:
\begin{proof}
  \uses{MeasureTheory.ringHaarChar_mul_volume}
  \leanok
  Multiplication by a positive real $r$ sends a unit square to a square of area $r^2=|r|^2$.
  Multiplication by $e^{i\theta}$ is a rotation and thus does not change area.
  The general case follows.
\end{proof}

n910.content:
\begin{proof}
  \uses{MeasureTheory.ringHaarChar_mul_volume}
  \leanok
  Normalise Haar measure so that $\mu(\mathbb{Z}_p)=1$.
  If $u$ is a $p$-adic unit then $u\mathbb{Z}_p=\mathbb{Z}_p$ so multiplication by $u$ didn't change
  Haar measure. If however $u=p$ then $u\mathbb{Z}_p$ has index $p$ in $\mathbb{Z}_p$ and, because
  $\mu(i+p\mathbb{Z}_p)=\mu(p\mathbb{Z}_p)$ we have that $\mu(\mathbb{Z}_p)=p\mu(p\mathbb{Z}_p)$ and thus $\delta(p)=p^{-1}$.
  These elements generate $\mathbb{Q}_p^\times$ and two characters which agree on generators
  of a group must agree on the group.
\end{proof}

n912.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det,
    MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det_of_existsListTransvecEtc}
  \lean{MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det,
    MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det_of_existsListTransvecEtc}
  \uses{MeasureTheory.ringHaarChar}
  \leanok
  \discussion{517}
  Assume that there's an $F$-basis for $V$ such that $\phi$ is a product of elementary
  and diagonal matrices (note that this is automatic if $F$ is a field and mathlib
  has this). Then
  $d_V(\phi)=\delta_F(\det(\phi))$, where $\det(\phi)\in F$ is the determinant of
  $\phi$ as an $F$-linear map.
\end{lemma}

n913.content:
\begin{proof}
\uses{MeasureTheory.addEquivAddHaarChar}
\leanok
The proof is a generalization of
\href{https://leanprover-community.github.io/mathlib4\_docs/Mathlib/MeasureTheory/Measure/Lebesgue/Basic.html\#Real.map\_matrix\_volume\_pi\_eq\_smul\_volume\_pi}
{\tt Real.map\_matrix\_volume\_pi\_eq\_smul\_volume\_pi},
which crucially uses the induction principle
\href{https://leanprover-community.github.io/mathlib4\_docs/Mathlib/LinearAlgebra/Matrix/Transvection.html\#Matrix.diagonal\_transvection\_induction\_of\_det\_ne\_zero}
{\tt Matrix.diagonal\_transvection\_induction\_of\_det\_ne\_zero}.
One checks it explicitly for diagonal matrices and for matrices which are the identity
except that one off-diagonal entry is non-zero.

Note: we assume that $F$ is second countable
(but it shouldn't be necessary).
\end{proof}

n915.content:
\begin{proof}
  \uses{MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det}
  \leanok
  Follows immediately from the preceding lemma.
\end{proof}

n916.content:
\begin{lemma}
  \label{IsSimpleRing.mulLeft_det_eq_mulRight_det}
  \lean{IsSimpleRing.mulLeft_det_eq_mulRight_det}
  \leanok
  \discussion{518}
  Say $B$ is a finite-dimensional central simple algebra over a field~$k$,
  and $u\in B^\times$. Let $\ell_u:B\to B$ be the $k$-linear mapping $x$ to $ux$ and
  let $r_u:B\to B$ be the $k$-linear map sending $x$ to $xu$. Then
  $\det(\ell_u)=\det(r_u)$.
\end{lemma}

n918.content:
\begin{corollary}
  \label{IsSimpleRing.ringHaarChar_eq_addEquivAddHaarChar_mulRight}
  \lean{IsSimpleRing.ringHaarChar_eq_addEquivAddHaarChar_mulRight}
  \leanok
  If $B$ is a central simple algebra over a locally compact field $F$, and if $u\in B^\times$,
  then $d_B(r_u)=\delta_B(u)$ (recall that the latter is defined to mean $d_B(\ell_u)$).
\end{corollary}

n919.content:
\begin{proof}
  \leanok
  \uses{IsSimpleRing.mulLeft_det_eq_mulRight_det, MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det}
  If $\ell_u$ and $r_u$ denote left and right multiplication by $u$ on $B$, then we have
  seen in lemma~\ref{MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det} that $d_B(r_u)=\delta_F(\det(r_u))$.
  Lemma~\ref{IsSimpleRing.mulLeft_det_eq_mulRight_det} tells
  us that this is $\delta_F(\det(\ell_u))$ and this is $\delta_B(u)$ again by
  corollary~\ref{MeasureTheory.addEquivAddHaarChar_eq_ringHaarChar_det}.
\end{proof}

n920.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_prodCongr}
  \lean{MeasureTheory.addEquivAddHaarChar_prodCongr}
  \leanok
  \discussion{520}
  If $(A,+)$ and $(B,+)$ are locally compact topological abelian groups,
  and if $\phi:A\to A$ and $\psi:B\to B$ are additive homeomorphisms,
  then $\phi\times\psi:A\times B\to A\times B$ is an additive homeomorphism (this is
  obvious), and
  $d_{A\times B}(\phi\times\psi)=d_A(\phi)d_B(\psi)$.
\end{lemma}

n922.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_piCongrRight}
  \lean{MeasureTheory.addEquivAddHaarChar_piCongrRight}
  \leanok
  \discussion{521}
  \uses{MeasureTheory.addEquivAddHaarChar_prodCongr}
  If $A_i$ are a finite collection of locally compact topological abelian groups,
  with $\phi_i:A_i\to A_i$ additive homeomorphisms, then $d_{\prod_i A_i}(\prod_i\phi_i)=\prod_i d_{A_i}(\phi_i)$.
\end{lemma}

n923.content:
\begin{proof}
  \leanok
  Induction on the size of the finite set, using the previous lemma.
\end{proof}

n924.content:
\begin{lemma}
  \label{MeasureTheory.ringHaarChar_prod}
  \lean{MeasureTheory.ringHaarChar_prod}
  \leanok
  \uses{MeasureTheory.addEquivAddHaarChar_prodCongr}
  If $R$ and $S$ are locally compact topological rings, then $\delta_{R\times S}(r,s)=\delta_R(r)\times\delta_S(s)$.
\end{lemma}

n926.content:
\begin{lemma}
  \label{MeasureTheory.ringHaarChar_pi}
  \lean{MeasureTheory.ringHaarChar_pi}
  \leanok
  \uses{MeasureTheory.addEquivAddHaarChar_piCongrRight}
  If $R_i$ are a finite collection of locally compact topological rings,
  and $u_i\in R_i^\times$ then $\delta_{\prod_i R_i}((u_i)_i)=\prod_i\delta_{R_i}(u_i)$.
\end{lemma}

n928.content:
\begin{lemma}
  \label{Topology.IsOpenEmbedding.isHaarMeasure_comap}
  \lean{Topology.IsOpenEmbedding.isHaarMeasure_comap}
  \leanok
  \discussion{507}
  Let $A$ and $B$ be locally compact topological groups
  and let $f:A\to B$ be both a group homomorphism and open embedding.
  The pullback along $f$ of a Haar measure on $B$ is a Haar measure on $A$.
\end{lemma}

n929.content:
\begin{proof}
  \leanok
  Translation-invariance is easy, compact sets are finite because continuous
  image of compact is compact, open sets are bounded because image of open is open.
\end{proof}

n930.content:
\begin{lemma}
  \label{Topology.IsOpenEmbedding.regular_comap}
  \lean{Topology.IsOpenEmbedding.regular_comap}
  \leanok
  \discussion{513}
  The pullback of a regular Borel measure along an open
  embedding is a regular Borel measure.
\end{lemma}

n931.content:
\begin{proof}
  \leanok
  Again this is because the image of compact is compact and the
  image of open is open, so all the properties of being a regular measure
  are easily checked.
\end{proof}

n932.content:
\begin{lemma}
  \label{MeasureTheory.mulEquivHaarChar_eq_one_of_compactSpace}
  \lean{MeasureTheory.mulEquivHaarChar_eq_one_of_compactSpace}
  \leanok
  \discussion{532}
  Say $A$ is a compact topological additive group and $\phi:A\to A$ is an additive isomorphism.
Then $d_A(\phi)=1.$
\end{lemma}

n933.content:
\begin{proof}
  \uses{MeasureTheory.mulEquivHaarChar_smul_preimage}
  \leanok
  We have $d_A(\phi)\mu(A)=\mu(A)$
  from lemma~\ref{MeasureTheory.addEquivAddHaarChar_smul_preimage}
  and $\mu(A)$ is positive and finite because $A$ is open and compact.
\end{proof}

n934.content:
\begin{lemma}
  \label{MeasureTheory.addEquivAddHaarChar_eq_addEquivAddHaarChar_of_isOpenEmbedding}
  \lean{MeasureTheory.addEquivAddHaarChar_eq_addEquivAddHaarChar_of_isOpenEmbedding}
  \leanok
  \discussion{551}
  If $f:A\to B$ is a group homomorphism and open embedding between locally compact
  topological additive groups and if $\alpha:A\to A$ and $\beta:B\to B$ are additive
  homeomorphisms such that the square commutes (i.e., $f\circ\alpha=\beta\circ f$)
  then $d_A(\alpha)=d_B(\beta)$.
\end{lemma}

n936.content:
\begin{lemma}
  \lean{Continuous.restrictedProduct_congrRight}
  \label{Continuous.restrictedProduct_congrRight}
  \leanok
  \discussion{531}
  If the $A_i$ and $B_i$ are topological spaces and the $\phi_i$ are continuous functions,
  then the restricted product $\phi = \prod'_i\phi_i$ is a continuous function.
\end{lemma}

n938.content:
\begin{theorem}
  \label{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight}
  \lean{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight}
  \leanok
  \discussion{552}
  With $A$, $A_i$, $C_i$, $\phi_i$, $\phi$ defined as above, we have
  $\delta_A(\phi)=\prod_i\delta_{A_i}(\phi_i)$.
\end{theorem}

n942.content:
\begin{proof}
  \leanok
  \uses{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight}
  By definition of restricted product we have $u_i\in C_i$ for all but finitely many $i$.
  Note also that $u$ has an inverse $v=(v_i)_i$ with $v_i\in C_i$ for all but finitely many $i$.
  The fact that $u_iv_i=v_iu_i=1$ means that $u_i,v_i\in C_i^\times$ for all but finitely many $i$.
  Thus the previous theorem~\ref{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight} applies.
\end{proof}

n943.content:
\begin{lemma}
  \label{IsModuleTopology.continuous_bilinear_of_finite_left}
  \lean{IsModuleTopology.continuous_bilinear_of_finite_left}
  \leanok
  Say $R$ and $S$ are topological rings, and $S$ is an $R$-algebra, finite as an $R$-module.
  Assume that the topology
  on $S$ is the $R$-module topology. Now say $M$ is an $S$-module, and give it the induced
  $R$-module structure. Then the $R$-module topology and $S$-module topology on~$M$ coincide.
\end{lemma}

n945.content:
\begin{corollary}
  \label{NumberField.AdeleRing.ModuleBaseChangeContinuousLinearEquiv}
  \lean{NumberField.AdeleRing.ModuleBaseChangeContinuousLinearEquiv}
  \leanok
  If $K$ is a number field and $V$ is an $K$-module, then
  the natural isomorphism $V\otimes_K\mathbb{A}_K=V\otimes_{\mathbb{Q}}\mathbb{A}_{\mathbb{Q}}$ induced by the natural
  isomorphism $\mathbb{A}_K=K\otimes_K\mathbb{A}_{\mathbb{Q}}$ is a homeomorphism if the left hand side has the $\mathbb{A}_K$-module
  topology and the right hand side has the $\mathbb{A}_{\mathbb{Q}}$-module topology.
\end{corollary}

n946.content:
\begin{proof}
  \leanok
  \uses{IsModuleTopology.continuous_bilinear_of_finite_left}
  Lemma~\ref{IsModuleTopology.continuous_bilinear_of_finite_left} tells us that $V\otimes_K\mathbb{A}_K$
  has the $\mathbb{A}_{\mathbb{Q}}$-module topology, and it is easily checked that the isomorphism is
  $\mathbb{A}_{\mathbb{Q}}$-linear and hence automatically continuous.

  Note that in the Lean we prove this for a general extension $L/K$ rather than $K/\mathbb{Q}$.
\end{proof}

n947.content:
\begin{theorem}
  \label{NumberField.AdeleRing.isCentralSimple_addHaarScalarFactor_left_mul_eq_right_mul}
  \lean{NumberField.AdeleRing.isCentralSimple_addHaarScalarFactor_left_mul_eq_right_mul}
  \leanok
  Let $B$ be a finite-dimensional central simple $K$-algebra.
  Say $u\in B_{\mathbb{A}}^\times$, and define $\ell_u$ and $r_u:B_{\mathbb{A}}\to B_{\mathbb{A}}$ by
  $\ell_u(x)=ux$ and $r_u(x)=xu$. Then $d_{B_{\mathbb{A}}}(\ell_u)=d_{B_{\mathbb{A}}}(r_u)$.
\end{theorem}

n948.content:
\begin{proof}
  \uses{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight,
    IsSimpleRing.ringHaarChar_eq_addEquivAddHaarChar_mulRight}
  We think of $B_{\mathbb{A}}$ as $B\otimes_K\mathbb{A}_K$.
  If $u=(u_v)$ as $v$ runs through the places of $K$ then
  $d_{B_{\mathbb{A}}}(\ell_u)=\prod_v d_{B_v}(\ell_{u_v})$ by
  theorem~\ref{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight} (and the product is finite).
  By corollary~\ref{IsSimpleRing.ringHaarChar_eq_addEquivAddHaarChar_mulRight}
  this equals $\prod_v d_{B_v}(r_{u_v})$, and again by
  theorem~\ref{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight} this is $d_{B_{\mathbb{A}}}(r_u)$.
\end{proof}

n950.content:
\begin{proof}
  \leanok
  \uses{MeasureTheory.addEquivAddHaarChar_prodCongr,MeasureTheory.ringHaarChar_real,
    MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight,MeasureTheory.ringHaarChar_padic}
  By theorem~\ref{MeasureTheory.addEquivAddHaarChar_prodCongr}
  we have $\delta_{\mathbb{A}_{\mathbb{Q}}}(x)=\delta_{\mathbb{A}_{\mathbb{Q}}^\infty}(x^\infty)\times\delta_{\mathbb{R}}(x_\infty)$.
  By lemma~\ref{MeasureTheory.ringHaarChar_real} we have $\delta_{\mathbb{R}}(x_\infty)=|x|_\infty$, and by
  theorem~\ref{MeasureTheory.addEquivAddHaarChar_restrictedProductCongrRight} we have
  $\delta_{\mathbb{A}_{\mathbb{Q}}^\infty}=\prod_p\delta_{\mathbb{Q}_p}(x_p)$. By lemma~\ref{MeasureTheory.ringHaarChar_padic}
  we have $\delta_{\mathbb{Q}_p}(x_p)=|x_p|_p$ and putting everything together we get the result.
\end{proof}

n952.content:
\begin{proof}
  \leanok
  \uses{MeasureTheory.ringHaarChar_adeles_rat}
  By lemma~\ref{MeasureTheory.ringHaarChar_adeles_rat} we have $\delta_{\mathbb{A}_{\mathbb{Q}}}(x)=\prod_v|x|_v$.
  But the product formula says that this is 1.
  A quick proof: if $x=\pm\prod_pp^{e_p}$ then $\prod_p|x|_p=\prod_pp^{-e_p}$
  and $|x|_\infty=\prod_pp^{e_p}$ so they cancel.
\end{proof}

n953.content:
\begin{theorem}
    \label{MeasureTheory.addHaarScalarFactor_tensor_adeles_eq_one}
    \lean{MeasureTheory.addHaarScalarFactor_tensor_adeles_eq_one}
    \leanok
    In the above situation ($V$ a finite-dimensional $\mathbb{Q}$-vector space, $\phi:V\cong V$ is
    $\mathbb{Q}$-linear, $\phi_{\mathbb{A}}$ the base extension to $V_{\mathbb{A}}:=V\otimes_{\mathbb{Q}}{\mathbb{A}_{\mathbb{Q}}}$, a continuous linear
    endomorphism of $V_{\mathbb{A}}$ with the $\mathbb{A}_{\mathbb{Q}}$-module topology), we have $d_{V_{\mathbb{A}}}(\phi_{\mathbb{A}})=1.$
  \end{theorem}

n955.content:
\begin{corollary}
    \label{NumberField.AdeleRing.units_mem_ringHaarCharacter_ker}
    \lean{NumberField.AdeleRing.units_mem_ringHaarCharacter_ker}
    \leanok
    If $B$ is a finite-dimensional $\mathbb{Q}$-algebra (for example a number field, or a quaternion algebra over a number field),
    if $B_{\mathbb{A}}$ denotes the ring $B\otimes_{\mathbb{Q}}\mathbb{A}_{\mathbb{Q}}$, and if $b\in B^\times$,
    then $\delta_{B_{\mathbb{A}}}(b)=1$.
  \end{corollary}

n956.content:
\begin{proof}
    \uses{MeasureTheory.addHaarScalarFactor_tensor_adeles_eq_one}
    \leanok
    Follows immediately from the previous theorem.
  \end{proof}

n957.content:
\begin{corollary}
    \label{NumberField.AdeleRing.addEquivAddHaarChar_mulRight_unit_eq_one}
    \lean{NumberField.AdeleRing.addEquivAddHaarChar_mulRight_unit_eq_one}
    \leanok
    If $B$ is a finite-dimensional $\mathbb{Q}$-algebra and
    if $b\in B^\times$ then right multiplication by $b$
    does not change Haar measure on $B_{\mathbb{A}}$.
  \end{corollary}

n958.content:
\begin{proof}
    \leanok
    \uses{MeasureTheory.addHaarScalarFactor_tensor_adeles_eq_one}
