  We let $E$ denote any compact set satisfying the hypothesis of the previous lemma.
\end{definition}

n966.content:
\begin{proof}
  \leanok
  It's the continuous image of the compact set~$E\times E$.
\end{proof}

n968.content:
\begin{proof}
